export type CompleteConversationInput = Readonly<{
  conversationId: string;
}>;

export class CompleteConversationUseCase extends UseCase<CompleteConversationInput, CompleteConversationResponse> {
  public readonly name = "CompleteConversation";
  public readonly version = 1;

  constructor(
    private readonly conversationStore: ConversationStore,
    private readonly eventDispatcher: EventDispatcher,
    private readonly clock: Clock,
    private readonly uuidGenerator: UuidGenerator,
    private readonly logger: Logger
  ) {
    super();
  }

  public async execute(input: CompleteConversationInput, processContext: Readonly<ProcessContext>): Promise<Result<CompleteConversationResponse, ApplicationError>> {
    this.logger.info(`Executing ${this.name}`, { conversationId: input.conversationId });

    // 1. validate
    if (!input.conversationId) {
      return err(new ValidationFailure("Invalid input", { input }));
    }
    const id = input.conversationId as Uuid;

    // 2. authorize (skip)

    // 3. load aggregate
    const findResult = await this.conversationStore.findById(id);
    if (!findResult.ok) {
      return findResult;
    }
    const conversation = findResult.value;
    const expectedRevision = conversation.revision;

    // 4. execute aggregate behavior
    const outcome = conversation.complete(this.uuidGenerator.generate(), this.clock.now());

    if (!outcome.success) {
      return err(new ConflictFailure(outcome.error));
    }

    // 5. persist
    if (!outcome.idempotent) {
      const saveResult = await this.conversationStore.save(conversation, expectedRevision);
      if (!saveResult.ok) {
        return saveResult; // Concurrency conflict
      }
    }

    // 6. publish events
    const releasedEvents = conversation.releaseEvents();
    if (releasedEvents.length > 0) {
      await this.eventDispatcher.dispatch(releasedEvents, processContext);
    }

    // 7. map response
    return ok({
      conversationId: conversation.id,
      idempotent: outcome.idempotent,
      revision: conversation.revision,
    });
  }
}

