    mockPort = {
      findById: vi.fn(),
      save: vi.fn(),
    };
    mockPublisher = {
      dispatch: vi.fn(),
    };
    mockClock = {
      now: vi.fn().mockReturnValue(new Date("2026-01-01T00:00:00Z")),
    };
    mockUuid = {
      generate: vi.fn().mockReturnValue("123e4567-e89b-12d3-a456-426614174000" as Uuid),
