    mockLogger = {
      info: vi.fn(),
      error: vi.fn(),
      warn: vi.fn(),
      debug: vi.fn(),
    };

    useCase = new ContinueConversationUseCase(mockPort, mockPublisher, mockClock, mockUuid, mockLogger);
  });

  it("should continue conversation and save it", async () => {
    const existing = Conversation.rehydrate(
      "test-id" as Uuid,
      { status: "open", stage: "qualification", followup_count: 0, conversation_id: "test-id" },
      { schema_version: 1, attachments: [], service_area_status: "unresolved" },
      1
    );

    vi.mocked(mockPort.findById).mockResolvedValue(ok(existing));
    vi.mocked(mockPort.save).mockResolvedValue(ok(undefined));

    const result = await useCase.execute({
      conversationId: "test-id",
      messageCount: 5,
    }, {} as never);

    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.value.idempotent).toBe(false);
      expect(result.value.revision).toBe(2);
    }

    expect(mockPort.save).toHaveBeenCalledOnce();
    expect(mockPublisher.dispatch).toHaveBeenCalledOnce();
  });

  it("should fail if conversation is completed", async () => {
    const existing = Conversation.rehydrate(
      "test-id" as Uuid,
      { status: "qualified", stage: "qualification", followup_count: 0, conversation_id: "test-id" },
      { schema_version: 1, attachments: [], service_area_status: "unresolved" },
      1
    );

    vi.mocked(mockPort.findById).mockResolvedValue(ok(existing));

    const result = await useCase.execute({
      conversationId: "test-id",
      messageCount: 5,
    }, {} as never);

    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error.code).toBe("CONFLICT_FAILURE");
    }

    expect(mockPort.save).not.toHaveBeenCalled();
  });

  it("should fail if conversation not found", async () => {
    vi.mocked(mockPort.findById).mockResolvedValue(err(new NotFoundError("Not found")));

    const result = await useCase.execute({
      conversationId: "test-id",
      messageCount: 5,
    }, {} as never);

    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error.code).toBe("NOT_FOUND");
    }
  });
});

