import type { AiOutput } from "../../../ai/contracts/ai-output-schema";
import type { ExtractedFacts, Attachment, Language, ProjectType, BudgetRange, Timeline } from "../../../../domain/conversation/conversation-facts";
import { ok, err, type Result } from "../../../../shared/result";
import type { ApplicationError } from "../../../../shared/errors/error";

export interface ParserFailure extends ApplicationError {
  readonly code: "ParserFailure";
  readonly version: number;
}

export function createParserFailure(version: number, message: string): ParserFailure {
  return {
    code: "ParserFailure",
    message,
    version,
  };
}

export interface AiOutputParserStrategy {
  parse(validatedContract: AiOutput): Result<ExtractedFacts, ParserFailure>;
}

export class V1ParserStrategy implements AiOutputParserStrategy {
  parse(validatedContract: AiOutput): Result<ExtractedFacts, ParserFailure> {
    // In V1, the contract already maps extremely closely to ExtractedFacts
    // so this mapping is trivial. In future versions, fields might be renamed.
    return ok(validatedContract.extractedFacts as ExtractedFacts);
  }
}

export class ConversationParser {
  private strategies = new Map<number, AiOutputParserStrategy>();

  constructor() {
    this.strategies.set(1, new V1ParserStrategy());
  }

  parse(schemaVersion: number, validatedContract: AiOutput): Result<ExtractedFacts, ParserFailure> {
    const strategy = this.strategies.get(schemaVersion);
    if (!strategy) {
      return err(createParserFailure(schemaVersion, `Unsupported schema version: ${schemaVersion}`));
    }

    return strategy.parse(validatedContract);
  }
}

import { describe, it, expect, vi } from "vitest";
import { ProcessUserMessageUseCase, type ProcessUserMessageCommand } from "./process-user-message-use-case";
import { ok, err } from "../../../../shared/result";
import type { PipelineStep } from "./steps/pipeline-step";
import type { ProcessContext, Uuid } from "../../../../shared/types";

describe("ProcessUserMessageUseCase", () => {
  const dummyContext: Readonly<ProcessContext> = {
    correlationId: "corr-1" as never,
    traceId: "trace-1" as never,
  };

  it("should short-circuit if a step fails", async () => {
    const step1: PipelineStep = {
      execute: vi.fn().mockResolvedValue(ok({ step1Run: true })),
    };
    const step2: PipelineStep = {
      execute: vi.fn().mockResolvedValue(err({ code: "TestError", message: "Failed" })),
    };
    const step3: PipelineStep = {
      execute: vi.fn(),
    };

    const useCase = new ProcessUserMessageUseCase([step1, step2, step3]);

    const result = await useCase.execute(
      { conversationId: "id-1" as Uuid, message: "Hello", expectedRevision: 1 },
      dummyContext
    );

    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error.code).toBe("TestError");
    }

    expect(step1.execute).toHaveBeenCalledOnce();
    expect(step2.execute).toHaveBeenCalledOnce();
    expect(step3.execute).not.toHaveBeenCalled();
  });

  it("should map response correctly if pipeline completes", async () => {
    const step1: PipelineStep = {
      execute: vi.fn().mockResolvedValue(ok({ response: { success: true } })),
    };

    const useCase = new ProcessUserMessageUseCase([step1]);

    const result = await useCase.execute(
      { conversationId: "id-1" as Uuid, message: "Hello", expectedRevision: 1 },
      dummyContext
    );

    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.value).toEqual({ success: true });
    }
  });
});

