import type { Uuid, Instant } from "../../../shared/types";
import type { ConversationState, ConversationFacts } from "../conversation-facts";
import type { DomainEvent } from "../../events/domain-event";
import {
  ConversationStartedEvent,
  ConversationContinuedEvent,
  ConversationCompletedEvent,
  ConversationReopenedEvent,
} from "../events";

export type ConversationActionOutcome =
  | { success: true; idempotent: boolean }
  | { success: false; error: string };

import type { ConversationAssessment } from "../recommendation";

export class Conversation {
  private _domainEvents: DomainEvent<string, Record<string, unknown>>[] = [];

  private constructor(
    public readonly id: Uuid,
    private _state: ConversationState,
    private _facts: ConversationFacts,
    private _revision: number
  ) {}

  public static start(id: Uuid): Conversation {
    const newState: ConversationState = {
      conversation_id: id,
      stage: "qualification",
      followup_count: 0,
      status: "open",
    };
    const newFacts: ConversationFacts = {
      schema_version: 1,
      attachments: [],
      service_area_status: "unresolved",
    };
    return new Conversation(id, newState, newFacts, 0);
  }

  public static rehydrate(id: Uuid, state: ConversationState, facts: ConversationFacts, revision: number): Conversation {
    return new Conversation(id, state, facts, revision);
  }

  public get state(): ConversationState {
    return this._state;
  }

  public get facts(): ConversationFacts {
    return this._facts;
  }

  public get revision(): number {
    return this._revision;
  }

  public releaseEvents(): readonly DomainEvent<string, Record<string, unknown>>[] {
    const events = [...this._domainEvents];
    this._domainEvents = [];
    return events;
  }

  public isCompleted(): boolean {
    return this._state.status === "qualified" || this._state.status === "won" || this._state.status === "lost";
  }

  public isActive(): boolean {
    return this._state.status === "open" || this._state.status === "consultation" || this._state.status === "estimate";
  }

  public applyFacts(
    mergedFacts: ConversationFacts,
    assessment: ConversationAssessment,
    source: string,
    eventId: Uuid,
    occurredAt: Instant
  ): ConversationActionOutcome {
    if (this.isCompleted()) {
      return { success: false, error: "Cannot apply facts to a completed conversation." };
    }

    this._facts = mergedFacts;
    // We could potentially transition state here based on assessment
    this._revision++;

    // In a real system, we might publish a FactsAppliedEvent
    // For now we just return success
    return { success: true, idempotent: false };
  }

  public start(source: string, eventId: Uuid, occurredAt: Instant): ConversationActionOutcome {
    if (this._revision > 0) {
      return { success: true, idempotent: true };
    }

    this._state = { ...this._state, status: "open" };
    this._revision++;

    this._domainEvents.push(
      new ConversationStartedEvent(eventId, occurredAt, {
        conversationId: this.id,
        startedAt: occurredAt,
        source,
      })
    );

    return { success: true, idempotent: false };
  }

  public continue(messageCount: number, eventId: Uuid, occurredAt: Instant): ConversationActionOutcome {
    if (this.isCompleted()) {
      return { success: false, error: "Cannot continue a completed conversation. Reopen it first." };
    }

    this._revision++;

    this._domainEvents.push(
      new ConversationContinuedEvent(eventId, occurredAt, {
        conversationId: this.id,
        continuedAt: occurredAt,
        messageCount,
        revision: this._revision,
      })
    );

    return { success: true, idempotent: false };
  }

  public complete(eventId: Uuid, occurredAt: Instant): ConversationActionOutcome {
    if (this.isCompleted()) {
      return { success: true, idempotent: true };
    }

    this._state = { ...this._state, status: "qualified" };
    this._revision++;

    this._domainEvents.push(
      new ConversationCompletedEvent(eventId, occurredAt, {
        conversationId: this.id,
        completedAt: occurredAt,
        revision: this._revision,
      })
    );

    return { success: true, idempotent: false };
  }

  public reopen(eventId: Uuid, occurredAt: Instant): ConversationActionOutcome {
    if (this.isActive()) {
      return { success: true, idempotent: true };
    }

    this._state = { ...this._state, status: "open" };
    this._revision++;

    this._domainEvents.push(
      new ConversationReopenedEvent(eventId, occurredAt, {
        conversationId: this.id,
        reopenedAt: occurredAt,
        revision: this._revision,
      })
    );

    return { success: true, idempotent: false };
  }
}

import { describe, it, expect } from "vitest";
import { CompletionPolicy } from "./completion-policy";
import type { CompletionRequirements } from "./completion-requirements";
import { CompletionStatus } from "./completion-decision";
import type { PolicyContext } from "../policy-context";
import type { ConversationState } from "../../index";

describe("Completion Policy", () => {
  const config: CompletionRequirements = {
    requiredFacts: [
      { field: "project_type", reason: "Need to know what project to build" },
      { field: "budget_range", reason: "Need budget to assess feasibility" }
    ]
  };

  const policy = new CompletionPolicy(config);

  const baseContext: PolicyContext = {
    state: {} as never,
    facts: { schema_version: 1, attachments: [] },
    assessment: { confidence: 100, readiness: 100, recommendation: "ask_followup", reasons: [], calculatedAt: new Date() }
  };

  it("should return MissingRequiredFacts when facts are missing", () => {
    const result = policy.evaluate(baseContext);
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.value.decision.status).toBe(CompletionStatus.MissingRequiredFacts);
      expect(result.value.decision.missingFacts.length).toBe(2);
      expect(result.value.explanations[0]!.code).toBe("MissingMandatoryFacts");
    }
  });

  it("should return Complete when all facts are present", () => {
    const completeContext: PolicyContext = {
      ...baseContext,
      facts: { ...baseContext.facts, project_type: "full_kitchen_remodel", budget_range: "15k_30k" }
    };
    const result = policy.evaluate(completeContext);
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.value.decision.status).toBe(CompletionStatus.Complete);
      expect(result.value.decision.missingFacts.length).toBe(0);
      expect(result.value.explanations[0]!.code).toBe("AllRequirementsMet");
    }
  });

  it("should return HumanHandoff when assessment recommends it, even if facts missing", () => {
    const handoffContext: PolicyContext = {
      ...baseContext,
      assessment: { ...baseContext.assessment, recommendation: "route_to_human" }
    };
    const result = policy.evaluate(handoffContext);
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.value.decision.status).toBe(CompletionStatus.HumanHandoff);
      expect(result.value.decision.missingFacts.length).toBe(0);
      expect(result.value.explanations[0]!.code).toBe("HumanHandoffRequested");
    }
  });
});

import { describe, it, expect } from "vitest";
import { PolicyEngine } from "./policy-engine";
import { PolicyRegistry } from "./policy-registry";
import type { ConversationPolicy } from "./conversation-policy";
import type { PolicyContext } from "./policy-context";
import { ok } from "../../../shared/result";
import type { PolicyResult } from "./policy-result";
import type { ConversationState } from "../index";
import type { ConversationAssessment } from "../recommendation";
import type { ConversationFacts } from "../conversation-facts";

describe("Policy Engine & Registry", () => {
  const dummyContext: PolicyContext = {
    state: {} as never,
    facts: {} as never as ConversationFacts,
    assessment: {} as never as ConversationAssessment,
  };

  it("should register and retrieve policies", () => {
    const registry = new PolicyRegistry();
    const mockPolicy: ConversationPolicy<unknown, unknown> = {
      name: "MockPolicy",
      version: "1.0.0",
      evaluate: () => ok({ decision: true, explanations: [], policyVersion: "1.0.0" }),
    };

    registry.register(mockPolicy);

    const result = registry.getPolicy<PolicyContext, PolicyResult<boolean>>("MockPolicy");
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.value.name).toBe("MockPolicy");
    }
  });

  it("should enforce unique policy registration", () => {
    const registry = new PolicyRegistry();
    const mockPolicy: ConversationPolicy<unknown, unknown> = {
      name: "MockPolicy",
      version: "1.0.0",
      evaluate: () => ok({ decision: true, explanations: [], policyVersion: "1.0.0" }),
    };

    registry.register(mockPolicy);
    expect(() => registry.register(mockPolicy)).toThrow("Policy MockPolicy is already registered.");
  });

  it("should evaluate a policy successfully via the engine", () => {
    const engine = new PolicyEngine();
    const mockPolicy: ConversationPolicy<PolicyContext, PolicyResult<boolean>> = {
      name: "MockPolicy",
      version: "1.0.0",
      evaluate: () => ok({ decision: true, explanations: [], policyVersion: "1.0.0" }),
    };

    const result = engine.evaluate(mockPolicy, dummyContext);
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.value.decision).toBe(true);
    }
  });
});

